ga34(){return"\ud83c\udfb0 \u041a\u043b\u0430\u0441\u0441\u0438\u043a\u0430"},
ga36(){return"\ud83d\udc02 \u0411\u04b1\u049b\u0430"},
ga35(){return"\ud83d\udcb0 \u0421\u0435\u0439\u0444"},
