ga2G(){return"\u27f3 \u0410\u0412\u0422\u041e"},
ga2F(){return"\ud83d\udfe1 \u041c\u043e\u043d\u0435\u0442\u0430\u043b\u0430\u0440 \u043a\u04e9\u0431\u0435\u0439\u0435\u0434\u0456 \u0436\u04d9\u043d\u0435 \u0441\u0435\u0439\u0444 \u0430\u0448\u044b\u043b\u0430\u0434\u044b\u2026"},
