a3m(a,b){return"10 \u0436\u043e\u043b\u0430\u049b, \u04b1\u0442\u044b\u0441 \u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \u0436\u043e\u043b\u0430\u049b\u049b\u0430 \u0431\u04e9\u043b\u0456\u043d\u0433\u0435\u043d \u0431\u04e9\u043b\u0456\u0433\u0456\u043d\u0435\u043d \u0435\u0441\u0435\u043f\u0442\u0435\u043b\u0435\u0434\u0456 (\u0441\u0442\u0430\u0432\u043a\u0430 \xf7 10). \ud83d\udc02 \u2014 WILD: \u043a\u0435\u0437 \u043a\u0435\u043b\u0433\u0435\u043d \u0441\u0438\u043c\u0432\u043e\u043b\u0434\u044b \u0430\u043b\u043c\u0430\u0441\u0442\u044b\u0440\u0430\u0434\u044b, \u04af\u0448 \u0431\u04b1\u049b\u0430 \u0435\u04a3 \u043a\u04e9\u043f \u0442\u04e9\u043b\u0435\u0439\u0434\u0456. \u041a\u0435\u0439\u0434\u0435 \u201c\u0411\u04b1\u049b\u0430 \u049b\u044b\u0437\u0443\u044b\u201d \u0431\u0430\u0441\u0442\u0430\u043b\u0430\u0434\u044b: \u0431\u0456\u0440 \u0441\u0438\u043c\u0432\u043e\u043b \u043c\u0435\u043d \u0431\u04b1\u049b\u0430\u043b\u0430\u0440 \u0431\u0430\u0440\u0430\u0431\u0430\u043d\u0434\u0430 \u049b\u0430\u043b\u0430\u0434\u044b, \u04b1\u0442\u044b\u0441 \u043a\u0435\u043b\u0433\u0435\u043d\u0448\u0435 \u049b\u0430\u0439\u0442\u0430 \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u044b\u043b\u0430\u0434\u044b (\u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \u043a\u0435\u043c\u0456\u043d\u0434\u0435 \xd7"+a+"). \u0411\u043e\u0441 \u0442\u043e\u0440\u0441\u044b\u0437 \u0442\u043e\u043b\u044b\u049b \u044d\u043a\u0440\u0430\u043d \xd7"+b+" \u0442\u04e9\u043b\u0435\u0439\u0434\u0456."},
a3k(a,b,c,d,e,f,g,h){return"20 \u0436\u043e\u043b\u0430\u049b \u0441\u043e\u043b\u0434\u0430\u043d \u043e\u04a3\u0493\u0430, \u04b1\u0442\u044b\u0441 \u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \u0436\u043e\u043b\u0430\u049b\u049b\u0430 \u0431\u04e9\u043b\u0456\u043d\u0433\u0435\u043d \u0431\u04e9\u043b\u0456\u0433\u0456\u043d\u0435\u043d \u0435\u0441\u0435\u043f\u0442\u0435\u043b\u0435\u0434\u0456 (\u0441\u0442\u0430\u0432\u043a\u0430 \xf7 20). \u041a\u0430\u0441\u043a\u0430\u0434\u0442\u0430\u0440: \u04b1\u0442\u0430\u0442\u044b\u043d \u0441\u0438\u043c\u0432\u043e\u043b\u0434\u0430\u0440 \u0436\u0430\u0440\u044b\u043b\u044b\u043f, \u0436\u043e\u0493\u0430\u0440\u044b\u0434\u0430\u043d \u0436\u0430\u04a3\u0430\u043b\u0430\u0440\u044b \u0442\u04af\u0441\u0435\u0434\u0456 \u2014 \u04b1\u0442\u044b\u0441 \u0431\u043e\u043b\u043c\u0430\u0439\u044b\u043d\u0448\u0430. \ud83c\udccf WILD \u043a\u0435\u0437 \u043a\u0435\u043b\u0433\u0435\u043d \u0441\u0438\u043c\u0432\u043e\u043b\u0434\u044b \u0430\u043b\u043c\u0430\u0441\u0442\u044b\u0440\u0430\u0434\u044b, \u0442\u0435\u043a \ud83c\udf81-\u0442\u0456 \u0435\u043c\u0435\u0441. \u041a\u0430\u0441\u043a\u0430\u0434\u0442\u0430\u0440\u0434\u0430\u043d \u043a\u0435\u0439\u0456\u043d \u044d\u043a\u0440\u0430\u043d\u0434\u0430 \ud83c\udf81: 3 \u2014 \u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \xd7"+a+" \u0436\u04d9\u043d\u0435 "+b+" \u0442\u0435\u0433\u0456\u043d \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u0443, 4 \u2014 \xd7"+c+" \u0436\u04d9\u043d\u0435 "+d+", 5 \u2014 \xd7"+e+" \u0436\u04d9\u043d\u0435 "+f+". \u0422\u0435\u0433\u0456\u043d \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u0443\u0434\u0430 \u0431\u04d9\u0440\u0456 \xd7"+g+", \u04af\u0448 \ud83c\udf81 \u0442\u0430\u0493\u044b +"+h+" \u0431\u0435\u0440\u0435\u0434\u0456."},
a3l(a,b,c){return"10 \u0436\u043e\u043b\u0430\u049b \u0441\u043e\u043b\u0434\u0430\u043d \u043e\u04a3\u0493\u0430, \u04b1\u0442\u044b\u0441 \u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \u0436\u043e\u043b\u0430\u049b\u049b\u0430 \u0431\u04e9\u043b\u0456\u043d\u0433\u0435\u043d \u0431\u04e9\u043b\u0456\u0433\u0456\u043d\u0435\u043d \u0435\u0441\u0435\u043f\u0442\u0435\u043b\u0435\u0434\u0456 (\u0441\u0442\u0430\u0432\u043a\u0430 \xf7 10). \u0416\u043e\u043b\u0430\u049b\u0442\u0430\u0440\u0434\u0430\u0493\u044b \u043c\u043e\u043d\u0435\u0442\u0430\u043b\u0430\u0440 \u0442\u04e9\u043b\u0435\u043c\u0435\u0439\u0434\u0456, \u0431\u0456\u0440\u0430\u049b \u044d\u043a\u0440\u0430\u043d\u0434\u0430 "+a+" \u043d\u0435\u043c\u0435\u0441\u0435 \u043e\u0434\u0430\u043d \u043a\u04e9\u043f \u043c\u043e\u043d\u0435\u0442\u0430 \u0441\u0435\u0439\u0444\u0442\u0456 \u0430\u0448\u0430\u0434\u044b: \u043c\u043e\u043d\u0435\u0442\u0430\u043b\u0430\u0440 \u043e\u0440\u043d\u044b\u043d\u0434\u0430 \u049b\u0430\u043b\u0430\u0434\u044b, \u049b\u0430\u043b\u0493\u0430\u043d \u0442\u043e\u0440\u043b\u0430\u0440 \u049b\u0430\u0439\u0442\u0430 \u0430\u0439\u043d\u0430\u043b\u0430\u0434\u044b. \u0421\u0456\u0437\u0434\u0435 "+b+" \u04d9\u0440\u0435\u043a\u0435\u0442 \u0431\u0430\u0440, \u0436\u0430\u04a3\u0430 \u043c\u043e\u043d\u0435\u0442\u0430 \u043e\u043b\u0430\u0440\u0434\u044b \u049b\u0430\u0439\u0442\u0430 \u043e\u0440\u043d\u0430\u0442\u0430\u0434\u044b. \u0421\u043e\u04a3\u044b\u043d\u0434\u0430 \u0431\u0430\u0440\u043b\u044b\u049b \u043c\u043e\u043d\u0435\u0442\u0430\u043b\u0430\u0440 \u0442\u04e9\u043b\u0435\u043d\u0435\u0434\u0456 (\u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \xd70,5 \u2026 \xd725), \u0430\u043b 15 \u0442\u043e\u0440\u0434\u044b \u043c\u043e\u043d\u0435\u0442\u0430\u0493\u0430 \u0442\u043e\u043b\u0442\u044b\u0440\u0441\u0430\u04a3\u044b\u0437, \u04af\u0441\u0442\u0456\u043d\u0435 \u04ae\u041b\u041a\u0415\u041d \xd7"+c+" \u0431\u0435\u0440\u0456\u043b\u0435\u0434\u0456."},
a3n(a,b,c,d,e){return"20 \u0436\u043e\u043b\u0430\u049b \u0441\u043e\u043b\u0434\u0430\u043d \u043e\u04a3\u0493\u0430, \u04b1\u0442\u044b\u0441 \u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \u0436\u043e\u043b\u0430\u049b\u049b\u0430 \u0431\u04e9\u043b\u0456\u043d\u0433\u0435\u043d \u0431\u04e9\u043b\u0456\u0433\u0456\u043d\u0435\u043d \u0435\u0441\u0435\u043f\u0442\u0435\u043b\u0435\u0434\u0456 (\u0441\u0442\u0430\u0432\u043a\u0430 \xf7 20). \u2b50 \u0428\u0435\u0440\u0438\u0444 \u2014 WILD. \u0411\u0430\u0440\u0430\u0431\u0430\u043d \u04af\u0441\u0442\u0456\u043d\u0434\u0435 \u043a\u04e9\u0431\u0435\u0439\u0442\u043a\u0456\u0448 \u0436\u043e\u043b\u0430\u0493\u044b \u0431\u0430\u0440: \u04d9\u0440 \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u0443\u0434\u0430 \xd71\u2026\xd715 \u0442\u04af\u0441\u0435\u0434\u0456 \u0434\u0435, \u0436\u043e\u043b\u0430\u049b\u0442\u0430\u0493\u044b \u0431\u0430\u0440\u043b\u044b\u049b \u04b1\u0442\u044b\u0441 \u0441\u043e\u0493\u0430\u043d \u043a\u04e9\u0431\u0435\u0439\u0442\u0456\u043b\u0435\u0434\u0456. \ud83d\udcdc \u043a\u0435\u0437 \u043a\u0435\u043b\u0433\u0435\u043d \u0436\u0435\u0440\u0434\u0435: 3 \u2014 \u0441\u0442\u0430\u0432\u043a\u0430\u043d\u044b\u04a3 \xd7"+a+" \u0436\u04d9\u043d\u0435 "+b+" \u0442\u0435\u0433\u0456\u043d \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u0443, 4 \u2014 "+c+", 5 \u2014 "+d+". \u0422\u0435\u0433\u0456\u043d \u0430\u0439\u043d\u0430\u043b\u0434\u044b\u0440\u0443\u0434\u0430 \u043a\u04e9\u0431\u0435\u0439\u0442\u043a\u0456\u0448 \u043a\u0435\u043c\u0456\u043d\u0434\u0435 \xd72, \u04af\u0448 \ud83d\udcdc \u0442\u0430\u0493\u044b +"+e+" \u0431\u0435\u0440\u0435\u0434\u0456."},
