gaAq(){return"\u0421\u0430\u0442\u0443\u0448\u044b\u043b\u0430\u0440\u0434\u044b\u04a3 \u0430\u0439\u0442\u0443\u044b\u043d\u0448\u0430, \u043c\u04b1\u043d\u0434\u0430\u0439 \u0445\u0430\u0431\u0430\u0440\u043b\u0430\u043d\u0434\u044b\u0440\u0443\u043b\u0430\u0440\u0493\u0430 \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\u0448\u044b\u043b\u0430\u0440 \u04d9\u0434\u0435\u0442\u0442\u0435\u0433\u0456\u0434\u0435\u043d \u0436\u0438\u0456 \u0436\u0430\u0437\u0430\u0434\u044b \u0436\u04d9\u043d\u0435 \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u0442\u0435\u0437\u0456\u0440\u0435\u043a \u0441\u0430\u0442\u0443 \u04af\u0448\u0456\u043d \u0431\u0430\u0493\u0430\u043d\u044b \u0430\u0437 \u0441\u0430\u0443\u0434\u0430\u043b\u0430\u0441\u0430\u0434\u044b."},
gaAj(){return"\u0421\u0430\u0442\u0443\u0448\u044b\u043b\u0430\u0440 \u0448\u0430\u0493\u044b\u043c\u0434\u0430\u043d\u0430\u0434\u044b: \u049b\u043e\u04a3\u044b\u0440\u0430\u0443\u043b\u0430\u0440 \u0434\u0435\u0440\u043b\u0456\u043a \u0436\u043e\u049b, \u0430\u043b \u0430\u0437 \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\u0448\u044b\u043b\u0430\u0440 \u0431\u0430\u0493\u0430 \u04d9\u043b\u0456 \u0442\u04e9\u043c\u0435\u043d\u0434\u0435\u0439\u0434\u0456 \u0434\u0435\u043f \u043a\u04af\u0442\u0435\u0434\u0456."},
aAi(a,b){return a+" \u0431\u0440\u0435\u043d\u0434\u0442\u0435\u0440\u0456\u043d\u0435 \u0436\u04d9\u043d\u0435 \u0431\u0430\u0441\u049b\u0430 "+b+" \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0456\u043d\u0435 \u049b\u0430\u0442\u044b\u0441\u0442\u044b."},
aAt(a){return"\u0416\u0430\u0493\u0434\u0430\u0439\u0434\u044b\u04a3 "+a+" \u0434\u0435\u0439\u0456\u043d \u0441\u043e\u0437\u044b\u043b\u0443\u044b \u043a\u04af\u0442\u0456\u043b\u0435\u0434\u0456, \u0441\u043e\u0434\u0430\u043d \u043a\u0435\u0439\u0456\u043d \u043d\u0430\u0440\u044b\u049b \u049b\u0430\u043b\u044b\u043f\u0442\u044b \u0441\u04b1\u0440\u0430\u043d\u044b\u0441\u049b\u0430 \u043e\u0440\u0430\u043b\u0430\u0434\u044b."},
