gaAr(){return"\u041a\u0435\u043b\u0435\u0441\u0456 \u04af\u0448 \u043a\u04af\u043d\u0434\u0435 \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\u0448\u044b\u043b\u0430\u0440 \u043c\u04b1\u043d\u0434\u0430\u0439 \u0445\u0430\u0431\u0430\u0440\u043b\u0430\u043d\u0434\u044b\u0440\u0443\u043b\u0430\u0440\u0493\u0430 \u0436\u0438\u0456\u0440\u0435\u043a \u0436\u0430\u0437\u0430\u0434\u044b. \u049a\u0430\u0437\u0456\u0440 \u0436\u0430\u0440\u0438\u044f\u043b\u0430\u0439\u0442\u044b\u043d \u0443\u0430\u049b\u044b\u0442."},
gaAk(){return"\u041a\u0435\u043b\u0435\u0441\u0456 \u04af\u0448 \u043a\u04af\u043d\u0434\u0435 \u043c\u04b1\u043d\u0434\u0430\u0439 \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0434\u0456 \u0435\u0440\u0456\u043a\u0441\u0456\u0437 \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0430\u0434\u044b. \u0421\u0430\u0442\u0443\u0434\u044b \u043a\u0435\u0439\u0456\u043d\u0433\u0435 \u049b\u0430\u043b\u0434\u044b\u0440\u0493\u0430\u043d \u0434\u04b1\u0440\u044b\u0441."},
gwz(){return"\u0410\u0432\u0442\u043e\u0425\u0430\u0431\u0430\u0440\u043b\u0430\u0440"},
