gaAf(){return"\u041e\u049b\u0443 \u2192"},
aAe(a,b){return a+" \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0456 "+b+" \u0434\u0435\u0439\u0456\u043d \u0441\u04b1\u0440\u0430\u043d\u044b\u0441\u049b\u0430 \u0438\u0435"},
aAd(a,b){return a+" \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0456 "+b+" \u0434\u0435\u0439\u0456\u043d \u0441\u04b1\u0440\u0430\u043d\u044b\u0441\u0442\u0430\u043d \u0442\u044b\u0441"},
aAg(a){return"\u0431\u04af\u0433\u0456\u043d, "+a},
aAh(a){return"\u043a\u0435\u0448\u0435, "+a},
gaAc(){return"\u041e\u049b\u0438\u0493\u0430 \u0436\u0430\u043b\u0493\u0430\u0441\u044b\u043f \u0442\u04b1\u0440\u0493\u0430\u043d\u0434\u0430, \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\u0448\u044b\u043b\u0430\u0440 \u043e\u0441\u044b \u0431\u0440\u0435\u043d\u0434\u0442\u0435\u0440\u0434\u0456\u04a3 \u0445\u0430\u0431\u0430\u0440\u043b\u0430\u043d\u0434\u044b\u0440\u0443\u043b\u0430\u0440\u044b\u043d\u0430 \u0436\u0438\u0456\u0440\u0435\u043a \u0436\u0430\u0437\u0430\u0434\u044b."},
gaAb(){return"\u041e\u049b\u0438\u0493\u0430 \u0436\u0430\u043b\u0493\u0430\u0441\u044b\u043f \u0442\u04b1\u0440\u0493\u0430\u043d\u0434\u0430, \u0441\u0430\u0442\u044b\u043f \u0430\u043b\u0443\u0448\u044b\u043b\u0430\u0440 \u043e\u0441\u044b \u0431\u0440\u0435\u043d\u0434\u0442\u0435\u0440\u0434\u0456\u04a3 \u0445\u0430\u0431\u0430\u0440\u043b\u0430\u043d\u0434\u044b\u0440\u0443\u043b\u0430\u0440\u044b\u043d\u0430 \u0441\u0438\u0440\u0435\u043a \u0436\u0430\u0437\u0430\u0434\u044b."},
gb2j(){return"\u26a0\ufe0f \u0422\u0456\u0440\u043a\u0435\u0443\u0433\u0435 \u0442\u044b\u0439\u044b\u043c \u0442\u0430\u0431\u044b\u043b\u0434\u044b!"},
gb2g(){return"\u26a0\ufe0f VIN \u043d\u04e9\u043c\u0456\u0440\u0456 \u049b\u0430\u0439\u0442\u0430 \u0431\u0430\u0441\u044b\u043b\u0493\u0430\u043d\u044b\u043d\u044b\u04a3 \u0431\u0435\u043b\u0433\u0456\u043b\u0435\u0440\u0456 \u0442\u0430\u0431\u044b\u043b\u0434\u044b!"},
