gzz(){return"\u0411\u0456\u0440\u0456\u043d\u0448\u0456 \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u0430\u043b\u043c\u0430 \u2014 \u0441\u0430\u0443\u0434\u0430\u043b\u0430\u0441, \u0441\u0435\u043d \u043e\u043d\u044b \u0431\u0456\u043b\u0435\u0441\u0456\u04a3 \ud83d\ude09 | \u041a\u04e9\u043b\u0456\u043a\u0442\u0456\u04a3 \u0442\u0430\u0440\u0438\u0445\u044b\u043d \u0442\u0435\u043a\u0441\u0435\u0440, \u04d9\u0439\u0442\u043f\u0435\u0441\u0435 \u0441\u0443\u0493\u0430 \u0431\u0430\u0442\u049b\u0430\u043d \u043a\u04e9\u043b\u0456\u043a \u0430\u043b\u0430\u0441\u044b\u04a3 | \u0411\u04d9\u0440\u0456\u043d \u0431\u0456\u0440\u0434\u0435\u043d \u0436\u04b1\u043c\u0441\u0430\u043c\u0430, \u0430\u0437\u0434\u0430\u043f \u0441\u0430\u043b\u044b\u043c\u0493\u0430 \u0441\u0430\u043b \ud83d\udcb8"},
