zq(a,b){return a+" \u0430\u0440\u049b\u044b\u043b\u044b "+b+" \u0442\u0430\u043f\u0442\u044b\u04a3 \u0431\u0430? \u041e\u0439\u043f\u044b\u0440\u043c\u0430\u0439! \ud83c\udf89 | "+b+" \u043f\u0430\u0439\u0434\u0430 \u2014 \u043d\u0430\u0493\u044b\u0437 \u0431\u0438\u0437\u043d\u0435\u0441\u043c\u0435\u043d \ud83d\ude0e | "+a+" \u0441\u0430\u0442\u044b\u043b\u0493\u0430\u043d\u044b\u043c\u0435\u043d \u049b\u04b1\u0442\u0442\u044b\u049b\u0442\u0430\u0439\u043c\u044b\u043d! \u0422\u043e\u0439\u043b\u0430\u0439\u043c\u044b\u0437 \u0431\u0430? \ud83e\udd42"},
zp(a){return a+" \u04af\u0448\u0456\u043d \u0440\u0435\u043d\u0436\u0456\u043c\u0435, \u0431\u043e\u043b\u0430\u0434\u044b \ud83e\udd17 | "+a+" \u0448\u044b\u0493\u044b\u043d\u043c\u0435\u043d \u043a\u0435\u0442\u0442\u0456 \u043c\u0435? \u041a\u0435\u043b\u0435\u0441\u0456 \u0436\u043e\u043b\u044b \u049b\u0430\u0439\u0442\u0430\u0440\u0430\u0441\u044b\u04a3 | \u0411\u04d9\u0440\u0456 \u0436\u0430\u049b\u0441\u044b \u0431\u043e\u043b\u0430\u0434\u044b, \u0441\u0430\u0493\u0430\u043d \u0441\u0435\u043d\u0435\u043c\u0456\u043d \ud83d\udc9b"},
gzv(){return"\u0416\u0430\u04a3\u0430 \u04af\u0439 \u043c\u0435?! \u041a\u04e9\u0440\u0441\u0435\u0442\u0435\u0441\u0456\u04a3 \u0431\u0435? \ud83c\udfe0 | \u0416\u0430\u04a3\u0430 \u04af\u0439\u0456\u04a3 \u049b\u04b1\u0442\u0442\u044b \u0431\u043e\u043b\u0441\u044b\u043d! \ud83c\udf89 | \u04e8\u0437 \u04af\u0439\u0456\u04a3 \u2014 \u0431\u0430\u0439 \u0431\u043e\u043b\u0434\u044b\u04a3 \u0493\u043e\u0439 \ud83d\ude04"},
