gWD(){return"\u0425\u043e\u0440\u043e\u0448\u043e, \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0438\u0441\u044c \u043d\u0430 \u043d\u043e\u0432\u043e\u0435 \u0432\u0440\u0435\u043c\u044f!"},
