aiw(a){return"\u0421\u043b\u0443\u0448\u0430\u0439, \u043c\u043e\u0436\u0435\u0448\u044c \u0437\u0430\u043d\u044f\u0442\u044c "+a+"? \u0412\u0435\u0440\u043d\u0443 \u0447\u0435\u0440\u0435\u0437 \u043f\u0430\u0440\u0443 \u043d\u0435\u0434\u0435\u043b\u044c"},
aix(a){return"\u0412\u044b\u0440\u0443\u0447\u0438\u0448\u044c "+a+"? \u041c\u0430\u0448\u0438\u043d\u0443 \u0434\u043e\u043a\u0443\u043f\u0438\u0442\u044c \u043d\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442, \u043e\u0442\u0434\u0430\u043c \u0441\u043a\u043e\u0440\u043e"},
aiy(a){return"\u041d\u0435\u0443\u0434\u043e\u0431\u043d\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c, \u043d\u043e \u0437\u0430\u0439\u043c\u0451\u0448\u044c "+a+"? \u0412\u0435\u0440\u043d\u0443, \u0447\u0435\u0441\u0442\u043d\u043e"},
aiT(a,b){return"\u041a\u043e\u043d\u0435\u0447\u043d\u043e! \u041f\u0435\u0440\u0435\u0432\u0435\u043b\u0430 "+a+". \u0422\u043e\u043b\u044c\u043a\u043e \u0432\u0435\u0440\u043d\u0438 \u0447\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439, \u043f\u0435\u043d\u0441\u0438\u044f \u043d\u0435 \u0440\u0435\u0437\u0438\u043d\u043e\u0432\u0430\u044f \ud83d\udc75"},
aj_(a,b){return"\u041f\u0435\u0440\u0435\u0432\u0435\u043b\u0430 "+a+". \u0412\u0435\u0440\u043d\u0451\u0448\u044c \u0447\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439, \u0445\u043e\u0440\u043e\u0448\u043e? \u2764\ufe0f"},
aj0(a){return"\u0414\u0435\u0440\u0436\u0438 "+a+". \u0422\u043e\u043b\u044c\u043a\u043e \u043d\u0435 \u0432 \u043a\u0430\u0437\u0438\u043d\u043e!"},
aj1(a,b){return"\u0421\u043a\u0438\u043d\u0443\u043b "+a+". \u0427\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439 \u0436\u0434\u0443 \u043e\u0431\u0440\u0430\u0442\u043d\u043e \u2014 \u0431\u0438\u0437\u043d\u0435\u0441 \u0435\u0441\u0442\u044c \u0431\u0438\u0437\u043d\u0435\u0441 \ud83d\udc4d"},
aj2(a){return"\u0414\u0435\u0440\u0436\u0438 "+a+". \u0412\u0435\u0440\u043d\u0438 \u0432 \u0441\u0440\u043e\u043a, \u043f\u0440\u043e\u0432\u0435\u0440\u044e \ud83d\ude09"},
