aj3(a,b){return"\u0411\u0440\u0430\u0442\u0430\u043d, \u043a\u0438\u043d\u0443\u043b "+a+". \u0427\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439 \u0432\u0435\u0440\u043d\u0438, \u043c\u043d\u0435 \u0437\u0430 \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u044c"},
aj4(a,b){return"\u0411\u0435\u0437 \u043f\u0440\u043e\u0431\u043b\u0435\u043c, "+a+" \u0443\u0448\u043b\u043e. \u041e\u0442\u0434\u0430\u0448\u044c \u0447\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439 \ud83e\udd1d"},
aj5(a,b){return"\u041b\u0430\u0434\u043d\u043e, \u0434\u0435\u0440\u0436\u0438 "+a+". \u0427\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439 \u0432\u0435\u0440\u043d\u0438, \u0430 \u0442\u043e \u043c\u0430\u043c\u0435 \u0440\u0430\u0441\u0441\u043a\u0430\u0436\u0443 \ud83d\ude0f"},
aiZ(a,b){return"\u041f\u0435\u0440\u0435\u0432\u0435\u043b\u0430 "+a+", \u0437\u043e\u043b\u043e\u0442\u0446\u0435. \u0412\u0435\u0440\u043d\u0451\u0448\u044c \u0447\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439 \ud83c\udf37"},
aiV(a,b){return"\u0414\u0435\u0440\u0436\u0438 "+a+". \u0412\u0435\u0440\u043d\u0438 \u0447\u0435\u0440\u0435\u0437 "+b+" \u0434\u043d\u0435\u0439"},
aiW(a){return"\u0421\u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0435\u0442, \u043c\u043e\u0433\u0443 \u0442\u043e\u043b\u044c\u043a\u043e "+a+". \u041f\u0435\u0440\u0435\u0432\u0435\u043b\u0430 \u2014 \u0432\u0435\u0440\u043d\u0451\u0448\u044c \u0432 \u0441\u0440\u043e\u043a"},
aiX(a){return"\u0412\u0441\u044e \u0441\u0443\u043c\u043c\u0443 \u043d\u0435 \u043f\u043e\u0442\u044f\u043d\u0443, \u0441\u043a\u0438\u043d\u0443\u043b "+a+". \u0412\u0435\u0440\u043d\u0438 \u0432\u043e\u0432\u0440\u0435\u043c\u044f, \u043b\u0430\u0434\u043d\u043e?"},
