gaiB(){return"\u041e\u0439, \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0438\u043a\u0430\u043a \u2014 \u043b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430 \u043a\u0443\u043f\u0438\u043b\u0430, \u0434\u043e \u043f\u0435\u043d\u0441\u0438\u0438 \u0435\u0449\u0451 \u043d\u0435\u0434\u0435\u043b\u044f \ud83d\ude14"},
gaiF(){return"\u0421\u0435\u0439\u0447\u0430\u0441 \u043d\u0435 \u043c\u043e\u0433\u0443, \u0441\u0430\u043c\u0438 \u0432 \u0440\u0435\u043c\u043e\u043d\u0442\u0435. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439 \u0447\u0435\u0440\u0435\u0437 \u043f\u0430\u0440\u0443 \u0434\u043d\u0435\u0439"},
gaiG(){return"\u0421\u0435\u0439\u0447\u0430\u0441 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0445 \u043d\u0435\u0442, \u0432\u0441\u0451 \u0432 \u0434\u0435\u043b\u0435. \u041f\u043e\u0437\u0436\u0435 \u0441\u043f\u0440\u043e\u0441\u0438"},
gaiC(){return"\u041d\u0435\u0442\u0443 \u0441\u0435\u0439\u0447\u0430\u0441, \u0432\u0441\u0451 \u043d\u0430 \u0434\u0430\u0447\u0443 \u0443\u0448\u043b\u043e. \u041f\u043e\u0442\u043e\u043c \u0441\u043f\u0440\u043e\u0441\u0438"},
