gaiS(){return"\u041d\u0435\u0442 \u0443\u0436, \u044f \u0437\u043d\u0430\u044e, \u0447\u0442\u043e \u0442\u044b \u0443\u0436\u0435 \u0437\u0430\u043d\u0438\u043c\u0430\u043b \u0443 \u043d\u0430\u0448\u0438\u0445. \u041e\u0442\u0434\u0430\u0439 \u0438\u043c \u2014 \u0442\u043e\u0433\u0434\u0430 \u043f\u0440\u0438\u0445\u043e\u0434\u0438."},
gajz(){return"\u041d\u0435\u0442. \u0412 \u043f\u0440\u043e\u0448\u043b\u044b\u0439 \u0440\u0430\u0437 \u0435\u043b\u0435 \u0434\u043e\u0436\u0434\u0430\u043b\u0438\u0441\u044c \u0441\u0432\u043e\u0438 \u0434\u0435\u043d\u044c\u0433\u0438."},
