gajB(){return"\u041d\u0435 \u0434\u0430\u043c. \u0422\u044b \u0432 \u043f\u0440\u043e\u0448\u043b\u044b\u0439 \u0440\u0430\u0437 \u043f\u0440\u043e\u043f\u0430\u043b \u0441 \u0434\u043e\u043b\u0433\u043e\u043c."},
aj6(a){return"\u0422\u044b \u043c\u043d\u0435 \u0435\u0449\u0451 "+a+" \u043d\u0435 \u0432\u0435\u0440\u043d\u0443\u043b(\u0430). \u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0434\u043e\u043b\u0433, \u043f\u043e\u0442\u043e\u043c \u043d\u043e\u0432\u044b\u0439."},
aj7(a){return"\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0432\u0435\u0440\u043d\u0438 "+a+", \u043f\u043e\u0442\u043e\u043c \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043c \ud83d\ude42"},
gaiz(){return"\u042f \u0436\u0435 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0443\u0436\u0435 \u043e\u0442\u0432\u0435\u0442\u0438\u043b(\u0430). \u0417\u0430\u0432\u0442\u0440\u0430 \u0441\u043f\u0440\u043e\u0441\u0438."},
gaiA(){return"\u0414\u0430\u0432\u0430\u0439 \u043d\u0435 \u0441\u0435\u0433\u043e\u0434\u043d\u044f, \u043b\u0430\u0434\u043d\u043e?"},
