ajI(a){return"\u041f\u0440\u0438\u0432\u0435\u0442! \u0421\u0440\u043e\u043a \u043f\u043e "+a+" \u043f\u043e\u0434\u043e\u0448\u0451\u043b, \u0432\u0435\u0440\u043d\u0451\u0448\u044c?"},
gaiM(){return"\u041d\u0435\u0434\u0435\u043b\u044f \u043f\u0440\u043e\u0448\u043b\u0430, \u0430 \u0434\u043e\u043b\u0433\u0430 \u0432\u0441\u0451 \u043d\u0435\u0442. \u0411\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u043f\u0440\u043e\u0441\u0438."},
