aiw(a){return"\u0421\u043b\u0443\u0445\u0430\u0439, \u043c\u043e\u0436\u0435\u0448 \u043f\u043e\u0437\u0438\u0447\u0438\u0442\u0438 "+a+"? \u041f\u043e\u0432\u0435\u0440\u043d\u0443 \u0437\u0430 \u043f\u0430\u0440\u0443 \u0442\u0438\u0436\u043d\u0456\u0432"},
aix(a){return"\u041c\u043e\u0436\u0435\u0448 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u0442\u0438 \u0437 "+a+"? \u0422\u0440\u0435\u0431\u0430 \u043d\u0430 \u043c\u0430\u0448\u0438\u043d\u0443, \u0441\u043a\u043e\u0440\u043e \u043f\u043e\u0432\u0435\u0440\u043d\u0443"},
aiy(a){return"\u041d\u0435\u0437\u0440\u0443\u0447\u043d\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u0438, \u0430\u043b\u0435 \u043c\u043e\u0436\u0435\u0448 \u043f\u043e\u0437\u0438\u0447\u0438\u0442\u0438 "+a+"? \u041f\u043e\u0432\u0435\u0440\u043d\u0443, \u0447\u0435\u0441\u043d\u043e"},
aiT(a,b){return"\u0417\u0432\u0456\u0441\u043d\u043e! \u041d\u0430\u0434\u0456\u0441\u043b\u0430\u043b\u0430 "+a+". \u0422\u0456\u043b\u044c\u043a\u0438 \u043f\u043e\u0432\u0435\u0440\u043d\u0438 \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432, \u043f\u0435\u043d\u0441\u0456\u044f \u0432 \u043c\u0435\u043d\u0435 \u043d\u0435 \u0431\u0435\u0437\u043c\u0435\u0436\u043d\u0430 \ud83d\udc75"},
aj_(a,b){return"\u041d\u0430\u0434\u0456\u0441\u043b\u0430\u043b\u0430 "+a+". \u041f\u043e\u0432\u0435\u0440\u043d\u0435\u0448 \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432, \u0434\u043e\u0431\u0440\u0435? \u2764\ufe0f"},
aj0(a){return"\u041e\u0441\u044c "+a+". \u0422\u0456\u043b\u044c\u043a\u0438 \u043d\u0435 \u043d\u0430 \u043a\u0430\u0437\u0438\u043d\u043e!"},
aj1(a,b){return"\u041d\u0430\u0434\u0456\u0441\u043b\u0430\u0432 "+a+". \u0427\u0435\u043a\u0430\u044e \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432 \u2014 \u0431\u0456\u0437\u043d\u0435\u0441 \u0454 \u0431\u0456\u0437\u043d\u0435\u0441 \ud83d\udc4d"},
aj2(a){return"\u041e\u0441\u044c "+a+". \u041f\u043e\u0432\u0435\u0440\u043d\u0438 \u0432\u0447\u0430\u0441\u043d\u043e, \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u044e \ud83d\ude09"},
