aj3(a,b){return"\u0411\u0440\u0430\u0442\u0435, \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u0432 "+a+". \u041f\u043e\u0432\u0435\u0440\u043d\u0438 \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432, \u0443 \u043c\u0435\u043d\u0435 \u043e\u0440\u0435\u043d\u0434\u0430 \ud83e\udd1d"},
aj4(a,b){return"\u0411\u0435\u0437 \u043f\u0440\u043e\u0431\u043b\u0435\u043c, "+a+" \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u043d\u043e. \u041f\u043e\u0432\u0435\u0440\u043d\u0435\u0448 \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432 \ud83e\udd1d"},
aj5(a,b){return"\u041b\u0430\u0434\u043d\u043e, \u043e\u0441\u044c "+a+". \u041f\u043e\u0432\u0435\u0440\u043d\u0438 \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432, \u0430 \u0442\u043e \u043c\u0430\u043c\u0456 \u0440\u043e\u0437\u043a\u0430\u0436\u0443 \ud83d\ude0f"},
aiZ(a,b){return"\u041d\u0430\u0434\u0456\u0441\u043b\u0430\u043b\u0430 "+a+", \u0441\u043e\u043d\u0435\u0447\u043a\u043e. \u041f\u043e\u0432\u0435\u0440\u043d\u0435\u0448 \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432 \ud83c\udf37"},
aiV(a,b){return"\u041e\u0441\u044c "+a+". \u041f\u043e\u0432\u0435\u0440\u043d\u0438 \u0437\u0430 "+b+" \u0434\u043d\u0456\u0432"},
aiW(a){return"\u0411\u0456\u043b\u044c\u0448\u0435 \u043d\u0435\u043c\u0430\u0454, \u043b\u0438\u0448\u0435 "+a+". \u041d\u0430\u0434\u0456\u0441\u043b\u0430\u0432 \u2014 \u043f\u043e\u0432\u0435\u0440\u043d\u0438 \u0432\u0447\u0430\u0441\u043d\u043e"},
aiX(a){return"\u0411\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u043c\u043e\u0436\u0443, \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u0432 "+a+". \u041f\u043e\u0432\u0435\u0440\u043d\u0438 \u0432\u0447\u0430\u0441\u043d\u043e, \u0434\u043e\u0431\u0440\u0435?"},
