gaiB(){return"\u041e\u0439, \u0437\u0430\u0440\u0430\u0437 \u043d\u0435 \u043c\u043e\u0436\u0443 \u2014 \u043a\u0443\u043f\u0438\u043b\u0430 \u043b\u0456\u043a\u0438, \u0434\u043e \u043f\u0435\u043d\u0441\u0456\u0457 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \ud83d\ude14"},
gaiF(){return"\u0417\u0430\u0440\u0430\u0437 \u043d\u0435 \u043c\u043e\u0436\u0443, \u0443 \u043d\u0430\u0441 \u0440\u0435\u043c\u043e\u043d\u0442. \u0421\u043f\u0440\u043e\u0431\u0443\u0439 \u0447\u0435\u0440\u0435\u0437 \u043f\u0430\u0440\u0443 \u0434\u043d\u0456\u0432"},
