a3m(a,b){return"10 \u043b\u0456\u043d\u0456\u0439, \u0432\u0438\u0433\u0440\u0430\u0448\u0456 \u0440\u0430\u0445\u0443\u044e\u0442\u044c\u0441\u044f \u0432\u0456\u0434 \u0441\u0442\u0430\u0432\u043a\u0438 \u043d\u0430 \u043b\u0456\u043d\u0456\u044e (\u0441\u0442\u0430\u0432\u043a\u0430 \xf7 10). \ud83d\udc02 \u2014 WILD: \u0437\u0430\u043c\u0456\u043d\u044e\u0454 \u0431\u0443\u0434\u044c-\u044f\u043a\u0438\u0439 \u0441\u0438\u043c\u0432\u043e\u043b, \u0442\u0440\u0438 \u0431\u0438\u043a\u0438 \u043f\u043b\u0430\u0442\u044f\u0442\u044c \u043d\u0430\u0439\u0431\u0456\u043b\u044c\u0448\u0435. \u0406\u043d\u043e\u0434\u0456 \u0432\u043c\u0438\u043a\u0430\u0454\u0442\u044c\u0441\u044f \xab\u041b\u044e\u0442\u044c \u0431\u0438\u043a\u0430\xbb: \u043e\u0434\u0438\u043d \u0441\u0438\u043c\u0432\u043e\u043b \u0456 \u0431\u0438\u043a\u0438 \u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u043d\u0430 \u0431\u0430\u0440\u0430\u0431\u0430\u043d\u0430\u0445, \u0456 \u043a\u0440\u0443\u0442\u0438\u0442\u044c\u0441\u044f, \u0434\u043e\u043a\u0438 \u043d\u0435 \u0432\u0438\u043f\u0430\u0434\u0435 \u0432\u0438\u0433\u0440\u0430\u0448 (\u0449\u043e\u043d\u0430\u0439\u043c\u0435\u043d\u0448\u0435 \xd7"+a+" \u0441\u0442\u0430\u0432\u043a\u0438). \u041f\u043e\u0432\u043d\u0438\u0439 \u0435\u043a\u0440\u0430\u043d \u0431\u0435\u0437 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u0445 \u043a\u043b\u0456\u0442\u0438\u043d\u043e\u043a \u043f\u043b\u0430\u0442\u0438\u0442\u044c \xd7"+b+"."},
a3k(a,b,c,d,e,f,g,h){return"20 \u043b\u0456\u043d\u0456\u0439 \u0437\u043b\u0456\u0432\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043e, \u0432\u0438\u0433\u0440\u0430\u0448\u0456 \u0440\u0430\u0445\u0443\u044e\u0442\u044c\u0441\u044f \u0432\u0456\u0434 \u0441\u0442\u0430\u0432\u043a\u0438 \u043d\u0430 \u043b\u0456\u043d\u0456\u044e (\u0441\u0442\u0430\u0432\u043a\u0430 \xf7 20). \u041a\u0430\u0441\u043a\u0430\u0434\u0438: \u0432\u0438\u0433\u0440\u0430\u0448\u043d\u0456 \u0441\u0438\u043c\u0432\u043e\u043b\u0438 \u043b\u043e\u043f\u0430\u044e\u0442\u044c\u0441\u044f, \u0456 \u0437\u0432\u0435\u0440\u0445\u0443 \u043f\u0430\u0434\u0430\u044e\u0442\u044c \u043d\u043e\u0432\u0456 \u2014 \u0434\u043e\u043a\u0438 \u0454 \u0432\u0438\u0433\u0440\u0430\u0448\u0456. \ud83c\udccf WILD \u0437\u0430\u043c\u0456\u043d\u044e\u0454 \u0431\u0443\u0434\u044c-\u044f\u043a\u0438\u0439 \u0441\u0438\u043c\u0432\u043e\u043b, \u043a\u0440\u0456\u043c \ud83c\udf81. \ud83c\udf81 \u043d\u0430 \u0435\u043a\u0440\u0430\u043d\u0456 \u043f\u0456\u0441\u043b\u044f \u043a\u0430\u0441\u043a\u0430\u0434\u0456\u0432: 3 \u2014 \xd7"+a+" \u0441\u0442\u0430\u0432\u043a\u0438 \u0456 "+b+" \u0431\u0435\u0437\u043a\u043e\u0448\u0442\u043e\u0432\u043d\u0438\u0445 \u0441\u043f\u0438\u043d\u0456\u0432, 4 \u2014 \xd7"+c+" \u0456 "+d+", 5 \u2014 \xd7"+e+" \u0456 "+f+". \u0423 \u0431\u0435\u0437\u043a\u043e\u0448\u0442\u043e\u0432\u043d\u0438\u0445 \u0441\u043f\u0438\u043d\u0430\u0445 \u0443\u0441\u0435 \xd7"+g+", \u0442\u0440\u0438 \ud83c\udf81 \u0434\u0430\u044e\u0442\u044c \u0449\u0435 +"+h+"."},
