gaJT(){return"\u041f\u043e\u043b\u0456\u0442\u0438\u043a\u0430 \u043a\u043e\u043d\u0444\u0456\u0434\u0435\u043d\u0446\u0456\u0439\u043d\u043e\u0441\u0442\u0456"},
gaJU(){return"\u041c\u0438 \u043e\u043d\u043e\u0432\u0438\u043b\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0430: \u0443 \u0433\u0440\u0456 \u0437\u0431\u0438\u0440\u0430\u0454\u0442\u044c\u0441\u044f \u0430\u043d\u043e\u043d\u0456\u043c\u043d\u0430 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430. \u041f\u043e\u0434\u0440\u043e\u0431\u0438\u0446\u0456 \u2014 \u0443 \u043f\u043e\u043b\u0456\u0442\u0438\u0446\u0456 \u043a\u043e\u043d\u0444\u0456\u0434\u0435\u043d\u0446\u0456\u0439\u043d\u043e\u0441\u0442\u0456."},
