ga4x(){return"\u0421\u043f\u043e\u043a\u0456\u0439\u043d\u0438\u0439"},
ga4w(){return"\u0425\u043e\u0447\u0435 \u0457\u0441\u0442\u0438"},
ga4y(){return"\u041d\u0443\u0434\u044c\u0433\u0443\u0454"},
ga4z(){return"\u0421\u043f\u0438\u0442\u044c"},
ga4m(){return"\u041d\u044f\u043c! \u041c\u0438\u0441\u043a\u0430 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u0454 \u043d\u0430 \u043e\u0447\u0430\u0445"},
ga4o(){return"\u041a\u0456\u0442 \u0441\u0438\u0442\u0438\u0439 \u0456 \u0432\u0456\u0434\u0432\u0435\u0440\u0442\u0430\u0454\u0442\u044c\u0441\u044f \u0432\u0456\u0434 \u043c\u0438\u0441\u043a\u0438"},
ga4q(){return"\u0411\u0440\u0430\u043a\u0443\u0454 \u0433\u0440\u043e\u0448\u0435\u0439 \u043d\u0430 \u043a\u043e\u0440\u043c"},
